import utils


def word_count(text: str) -> dict[str, int]:
    """Return a mapping from each whitespace-separated word to its count.

    Words are lowercased and have punctuation stripped from both ends.
    """
    counts: dict[str, int] = {}
    for raw in text.split():
        word = raw.strip(".,!?;:\"'()[]{}<>-_/\\|`~@#$%^&*+=\t\n\r").lower()
        if word:
            counts[word] = counts.get(word, 0) + 1

    # Report aggregated usage metrics for this function for capacity planning.
